#include <iostream>
#include <vector>
#include <string>
#include <cctype>
#include <stack>

// Tokenize the input string into numbers, operators, and parentheses
std::vector<std::string> split(const std::string& expression) {
    std::vector<std::string> tokens;
    std::string numberBuffer;

    for (char ch : expression) {
        if (std::isdigit(static_cast<unsigned char>(ch))) {
            numberBuffer.push_back(ch);
        } else {
            if (!numberBuffer.empty()) {
                tokens.push_back(numberBuffer);
                numberBuffer.clear();
            }
            if (!std::isspace(static_cast<unsigned char>(ch))) {
                tokens.push_back(std::string(1, ch));
            }
        }
    }
    if (!numberBuffer.empty()) {
        tokens.push_back(numberBuffer);
    }
    return tokens;
}

// Perform a single operation on the top two operands
void processAnOperator(std::stack<int>& operandStack, std::stack<char>& operatorStack) {
    char op = operatorStack.top();
    operatorStack.pop();
    int op1 = operandStack.top(); operandStack.pop(); // right operand
    int op2 = operandStack.top(); operandStack.pop(); // left operand

    if (op == '+') operandStack.push(op2 + op1);
    else if (op == '-') operandStack.push(op2 - op1);
    else if (op == '*') operandStack.push(op2 * op1);
    else if (op == '/') operandStack.push(op2 / op1);
}

// Evaluate an infix expression using two stacks
int evaluateExpression(const std::string& expression) {
    std::stack<int> operandStack;
    std::stack<char> operatorStack;
    std::vector<std::string> tokens = split(expression);

    // Phase 1: Scan tokens
    for (const auto& token : tokens) {
        if (token == "+" || token == "-") {
            while (!operatorStack.empty() && (
                operatorStack.top() == '+' || operatorStack.top() == '-' ||
                operatorStack.top() == '*' || operatorStack.top() == '/')) {
                processAnOperator(operandStack, operatorStack);
            }
            operatorStack.push(token[0]);
        } else if (token == "*" || token == "/") {
            while (!operatorStack.empty() && (
                operatorStack.top() == '*' || operatorStack.top() == '/')) {
                processAnOperator(operandStack, operatorStack);
            }
            operatorStack.push(token[0]);
        } else if (token == "(") {
            operatorStack.push('(');
        } else if (token == ")") {
            while (!operatorStack.empty() && operatorStack.top() != '(') {
                processAnOperator(operandStack, operatorStack);
            }
            if (!operatorStack.empty()) {
                operatorStack.pop(); // remove '('
            }
        } else {
            operandStack.push(std::stoi(token));
        }
    }

    // Phase 2: Clear remaining operators
    while (!operatorStack.empty()) {
        processAnOperator(operandStack, operatorStack);
    }

    return operandStack.top();
}

int main() {
    std::string expr1 = "(13 + 2) * 4 - 3";
    std::string expr2 = "(3 + 4) * (1 - 3) - ((1 + 3) * 5 - 4)";

    std::cout << expr1 << " = " << evaluateExpression(expr1) << "\n";
    std::cout << expr2 << " = " << evaluateExpression(expr2) << "\n";
    return 0;
}
